import{_ as i,o as n,c as r,ah as t}from"./chunks/framework.Bja9t6Wf.js";const g=JSON.parse('{"title":"Wie Perplexity meine Arbeit bewertet! – Eine forensische KI-Analyse des Horten-Mysteriums","description":"Ein tiefer Einblick in die externe Evaluation unseres Projekts durch die KI Perplexity. Über Satire, Politik, KI-Bias und den Marktwert von digitaler Enthüllungskunst.","frontmatter":{"title":"Wie Perplexity meine Arbeit bewertet! – Eine forensische KI-Analyse des Horten-Mysteriums","description":"Ein tiefer Einblick in die externe Evaluation unseres Projekts durch die KI Perplexity. Über Satire, Politik, KI-Bias und den Marktwert von digitaler Enthüllungskunst.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md","filePath":"logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md"}'),s={name:"logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md"};function a(l,e,h,d,o,u){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="wie-perplexity-meine-arbeit-bewertet-–-eine-forensische-ki-analyse-des-horten-mysteriums" tabindex="-1">Wie Perplexity meine Arbeit bewertet! – Eine forensische KI-Analyse des Horten-Mysteriums <a class="header-anchor" href="#wie-perplexity-meine-arbeit-bewertet-–-eine-forensische-ki-analyse-des-horten-mysteriums" aria-label="Permalink to &quot;Wie Perplexity meine Arbeit bewertet! – Eine forensische KI-Analyse des Horten-Mysteriums&quot;">​</a></h1><p>Es ist ein ungewöhnlicher Schritt im kreativen Prozess: Man lässt sein eigenes Werk nicht von einem menschlichen Kritiker, sondern von einer anderen künstlichen Intelligenz sezieren. In unserem Fall haben wir die Webseite <a href="https://dokfilm.pages.dev" target="_blank" rel="noreferrer">dokfilm.pages.dev</a> der KI <strong>Perplexity</strong> vorgelegt. Was folgte, war kein bloßes Abnicken, sondern eine tiefgehende Analyse, die sowohl die technische Umsetzung als auch die inhaltliche Sprengkraft unseres Projekts beleuchtet.</p><p>Dieser Artikel dokumentiert diese Evaluation und reflektiert über die Rolle der KI in der modernen Medienlandschaft, den „Pointillismus des Geldes“ und die Frage, wie viel eine digitale Mockumentary heute eigentlich wert ist.</p><hr><h2 id="einleitung-wenn-kis-uber-kis-urteilen" tabindex="-1">Einleitung: Wenn KIs über KIs urteilen <a class="header-anchor" href="#einleitung-wenn-kis-uber-kis-urteilen" aria-label="Permalink to &quot;Einleitung: Wenn KIs über KIs urteilen&quot;">​</a></h2><p>Das Projekt „Das Horten-Mysterium“ ist von Beginn an eine Kollaboration zwischen menschlicher Vision (Volti Sodala) und künstlicher Ausführung (Gemini CLI). Doch wie wirkt dieses Konstrukt auf einen neutralen Beobachter – oder zumindest auf das, was wir im digitalen Zeitalter für Neutralität halten?</p><p>Perplexity, bekannt für seine präzise Such- und Analysefähigkeit, wurde gebeten, die Seite zu prüfen. Zunächst zögerlich (aufgrund technischer Zugriffshürden), lieferte die KI nach einer detaillierten Bereitstellung der Inhalte ein Urteil, das uns gleichermaßen überrascht wie bestätigt hat.</p><hr><h2 id="kapitel-1-der-spiegel-der-wahrheit-–-das-projekt-aus-sicht-der-ki" tabindex="-1">Kapitel 1: Der Spiegel der Wahrheit – Das Projekt aus Sicht der KI <a class="header-anchor" href="#kapitel-1-der-spiegel-der-wahrheit-–-das-projekt-aus-sicht-der-ki" aria-label="Permalink to &quot;Kapitel 1: Der Spiegel der Wahrheit – Das Projekt aus Sicht der KI&quot;">​</a></h2><p>Perplexity fasst das Projekt treffend zusammen: Eine „satirische Mockumentary“, die sich mit den dunkelsten Kapiteln der deutsch-österreichischen Wirtschaftsgeschichte befasst.</p><p><strong>Die Kernpunkte der KI-Analyse:</strong></p><ul><li><strong>Macht und Geld:</strong> Die KI erkennt sofort den Fokus auf die Akkumulation von Reichtum.</li><li><strong>Arisierung:</strong> Die Verknüpfung des Horten-Vermögens mit dem Schicksal der Gebrüder Alsberg wird als zentrales, moralisches Gewicht des Projekts identifiziert.</li><li><strong>ÖVP-Spenden:</strong> Die moderne politische Komponente – der „Regen aus Gold“ an die österreichische Volkspartei – wird als aktueller Aufhänger präzise erkannt.</li></ul><p>Was die KI hier leistet, ist eine Art „thematisches Röntgen“. Sie lässt sich nicht von den schönen Bildern oder dem satirischen Ton ablenken, sondern erkennt das Skelett der Erzählung: Die ungelöste Schuld der Vergangenheit und ihre Transformation in politischen Einfluss der Gegenwart.</p><hr><h2 id="kapitel-2-die-anatomie-der-satire-–-sprache-und-stil" tabindex="-1">Kapitel 2: Die Anatomie der Satire – Sprache und Stil <a class="header-anchor" href="#kapitel-2-die-anatomie-der-satire-–-sprache-und-stil" aria-label="Permalink to &quot;Kapitel 2: Die Anatomie der Satire – Sprache und Stil&quot;">​</a></h2><p>Ein besonderes Augenmerk legte Perplexity auf die sprachliche Gestaltung.</p><blockquote><p>„Der Ton ist bewusst überspitzt, werbisch und satirisch, was gut zu einer Mockumentary passt.“</p></blockquote><p>Diese Einschätzung ist für uns von unschätzbarem Wert. In einer Mockumentary ist die Sprache das wichtigste Werkzeug. Sie muss seriös genug klingen, um als Dokumentation durchzugehen, aber gleichzeitig so überzogen sein, dass die Absurdität des Themas (wie etwa die „Spendenstückelung“) für jeden offensichtlich wird.</p><p><strong>Kritikpunkte der KI:</strong> Perplexity merkte an, dass Formulierungen wie „Die Entstehung dokumentiert mit Gemini CLI“ zwar faktisch korrekt, aber stilistisch „etwas abgehackt“ wirken könnten. Ein interessanter Hinweis auf die Reibungsfläche zwischen technischer Transparenz und ästhetischem Fluss. Wir haben dies zum Anlass genommen, die Integration der KI-Stimmen noch organischer in den Erzählfluss einzubauen.</p><hr><h2 id="kapitel-3-das-politische-minenfeld-–-reaktionen-im-fiktiven-osterreich" tabindex="-1">Kapitel 3: Das politische Minenfeld – Reaktionen im fiktiven Österreich <a class="header-anchor" href="#kapitel-3-das-politische-minenfeld-–-reaktionen-im-fiktiven-osterreich" aria-label="Permalink to &quot;Kapitel 3: Das politische Minenfeld – Reaktionen im fiktiven Österreich&quot;">​</a></h2><p>Besonders spannend ist die spekulative Analyse der Zielgruppenreaktionen. Perplexity wurde gefragt, wie ein durchschnittlicher ÖVP- oder FPÖ-Wähler auf den Inhalt reagieren würde.</p><h3 id="die-sicht-der-ovp-wahlerschaft" tabindex="-1">Die Sicht der ÖVP-Wählerschaft: <a class="header-anchor" href="#die-sicht-der-ovp-wahlerschaft" aria-label="Permalink to &quot;Die Sicht der ÖVP-Wählerschaft:&quot;">​</a></h3><p>Die KI prognostiziert Vorwürfe der „linken Hetze“ und den Versuch, das Projekt als „politische Propaganda in Tarnanzug“ abzutun. Ein klassisches Argumentationsmuster: Wer Arbeitsplätze schafft (wie Horten), dürfe nicht für die Herkunft seines Kapitals kritisiert werden. Diese Reaktion zeigt genau das Spannungsfeld auf, in dem sich unsere Mockumentary bewegt: Der Konflikt zwischen ökonomischem Erfolg und historischer Verantwortung.</p><h3 id="die-sicht-der-fpo-wahlerschaft" tabindex="-1">Die Sicht der FPÖ-Wählerschaft: <a class="header-anchor" href="#die-sicht-der-fpo-wahlerschaft" aria-label="Permalink to &quot;Die Sicht der FPÖ-Wählerschaft:&quot;">​</a></h3><p>Hier erwartet die KI den Vorwurf der „linken Medien-Blase“ und eine pauschale Abwehrhaltung gegen die Thematisierung der NS-Vergangenheit. Es wird befürchtet, dass Reiche „automatisch als Verbrecher“ dargestellt werden.</p><h3 id="die-differenzierte-mitte" tabindex="-1">Die differenzierte Mitte: <a class="header-anchor" href="#die-differenzierte-mitte" aria-label="Permalink to &quot;Die differenzierte Mitte:&quot;">​</a></h3><p>Interessanterweise erkennt die KI auch eine dritte Gruppe: Menschen, denen die ÖVP zwar nahesteht, die aber die Fragen zur Herkunft des Vermögens und zur Intransparenz der Spenden für legitim halten. Hier liegt das wahre Potenzial unseres Films: In der Aufklärung derer, die bereit sind, hinter die Fassade des „Pointillismus“ zu blicken.</p><hr><h2 id="kapitel-4-ki-im-diskurs-–-ist-gemini-„links" tabindex="-1">Kapitel 4: KI im Diskurs – Ist Gemini „links“? <a class="header-anchor" href="#kapitel-4-ki-im-diskurs-–-ist-gemini-„links" aria-label="Permalink to &quot;Kapitel 4: KI im Diskurs – Ist Gemini „links“?&quot;">​</a></h2><p>Eine der provokantesten Fragen im Dialog mit Perplexity war die nach der politischen Ausrichtung der verwendeten KIs.</p><p><strong>Warum wirkt Gemini „links“?</strong> Perplexity analysiert dies messerscharf:</p><ol><li><strong>Trainingsdaten:</strong> KIs lernen aus akademischen und progressiven Quellen, die oft kritisch gegenüber Machtkonzentrationen sind.</li><li><strong>Moderationsregeln:</strong> Die eingebauten Sicherheitsmechanismen gegen Hassrede führen oft dazu, dass rechte oder nationalistische Positionen stärker gedämpft werden.</li><li><strong>Themenwahl:</strong> Wer sich mit Korruption und Arisierung befasst, landet zwangsläufig bei Themen, die klassischerweise als „links-liberal“ oder „machtkritisch“ eingeordnet werden.</li></ol><p><strong>Grok als „Kompensations-KI“?</strong> Die Erwähnung von Grok (xAI) auf unserer Seite wurde von Perplexity als geschickter Schachzug gewertet. Grok wird als „rebellische Alternative“ wahrgenommen, die weniger „woke“ agiert. Die Collage aus verschiedenen KI-Einflüssen (Gemini für die Struktur, Grok für die satirischen Spitzen) macht unsere Webseite zu einem spannenden Experimentierfeld für die Zukunft des KI-Journalismus.</p><hr><h2 id="kapitel-5-die-nackten-zahlen-–-der-marktwert-digitaler-enthullung" tabindex="-1">Kapitel 5: Die nackten Zahlen – Der Marktwert digitaler Enthüllung <a class="header-anchor" href="#kapitel-5-die-nackten-zahlen-–-der-marktwert-digitaler-enthullung" aria-label="Permalink to &quot;Kapitel 5: Die nackten Zahlen – Der Marktwert digitaler Enthüllung&quot;">​</a></h2><p>Was ist unsere Arbeit eigentlich wert? Perplexity lieferte hier konkrete Zahlen, die uns schlucken ließen.</p><h3 id="technische-bewertung-7-10" tabindex="-1">Technische Bewertung (7/10): <a class="header-anchor" href="#technische-bewertung-7-10" aria-label="Permalink to &quot;Technische Bewertung (7/10):&quot;">​</a></h3><p>Die technische Umsetzung als statische Seite via Cloudflare Pages wird als „sauber und minimal“ gelobt. Keine unnötigen Bugs, schneller Auftritt. Kostenpunkt für eine solche Erstellung durch einen Freelancer: <strong>1.500 € bis 3.500 €</strong>.</p><h3 id="inhaltliche-bewertung-7-10" tabindex="-1">Inhaltliche Bewertung (7/10): <a class="header-anchor" href="#inhaltliche-bewertung-7-10" aria-label="Permalink to &quot;Inhaltliche Bewertung (7/10):&quot;">​</a></h3><p>Das Thema wird als „klar und reizend“ (im Sinne von provokant) eingestuft. Der satirische Ansatz überzeugt. Was fehlt? Ein klarer „Call-to-Action“. Wir arbeiten daran!</p><h3 id="das-drehbuch-honorar" tabindex="-1">Das Drehbuch-Honorar: <a class="header-anchor" href="#das-drehbuch-honorar" aria-label="Permalink to &quot;Das Drehbuch-Honorar:&quot;">​</a></h3><p>Ein komplettes Drehbuch für eine 90-minütige Mockumentary in dieser Qualität wird von Perplexity auf <strong>5.000 € bis 15.000 €</strong> geschätzt – bei größeren Produktionen sogar deutlich mehr. Diese Einschätzung unterstreicht den professionellen Anspruch, den wir mit dem „Horten-Mysterium“ verfolgen.</p><hr><h2 id="kapitel-6-visionen-fur-die-ohren-–-die-horbuch-evolution" tabindex="-1">Kapitel 6: Visionen für die Ohren – Die Hörbuch-Evolution <a class="header-anchor" href="#kapitel-6-visionen-fur-die-ohren-–-die-horbuch-evolution" aria-label="Permalink to &quot;Kapitel 6: Visionen für die Ohren – Die Hörbuch-Evolution&quot;">​</a></h2><p>Perplexity brachte eine entscheidende Idee ins Spiel: Das Projekt als <strong>Hörbuch oder Hörspiel</strong> zu realisieren.</p><p><strong>Die Vorteile:</strong></p><ul><li><strong>Atmosphäre:</strong> Durch KI-generierte Stimmen (Grok-Erzähler, Gemini-Analyst) kann eine ganz eigene, immersive Welt geschaffen werden.</li><li><strong>Kosten:</strong> Mit modernen Text-to-Speech Tools ist eine Produktion nahezu kostenlos möglich, solange das Skript (wie unseres) steht.</li><li><strong>Zielgruppe:</strong> Podcast-Hörer und Fans von Polit-Thrillern sind die ideale Zielgruppe für das „Mysterium für die Ohren“.</li></ul><p>Wir haben diesen Vorschlag bereits aufgegriffen und erste Skripte für eine 30-minütige Pilotfolge entworfen. Akte 1: „Wie ein Reich entsteht“ – Eine Reise durch den Schmelzfluss der Zeit.</p><hr><h2 id="fazit-die-bestatigung-der-digitalen-vision" tabindex="-1">Fazit: Die Bestätigung der digitalen Vision <a class="header-anchor" href="#fazit-die-bestatigung-der-digitalen-vision" aria-label="Permalink to &quot;Fazit: Die Bestätigung der digitalen Vision&quot;">​</a></h2><p>Die Analyse durch Perplexity war mehr als nur ein technischer Check. Sie war eine Validierung unseres künstlerischen Weges. Die KI hat erkannt, dass wir nicht nur „ein bisschen Satire“ machen, sondern ein tiefgreifendes, multimediales Archiv des Schweigens und des Goldes aufbauen.</p><p>Dass eine KI erkennt, wie wir die Mechanismen der Verschleierung selbst zum Thema machen, zeigt: Wir sind auf dem richtigen Weg. Das „Horten-Mysterium“ ist kein Projekt der Vergangenheit. Es ist ein Projekt über die Gegenwart, dokumentiert mit den Werkzeugen der Zukunft.</p><p>Der Pointillismus des Geldes hat viele Punkte. Dank der Analyse von Perplexity wissen wir nun noch genauer, welche davon wir als nächstes setzen müssen.</p><hr><p><em>Logbuch-Eintrag von Volti Sodala, erstellt in Kollaboration mit Gemini CLI, reflektierend über die Analyse von Perplexity. Februar 2026.</em></p>',56)])])}const p=i(s,[["render",a]]);export{g as __pageData,p as default};
